1	//! Contract module which provides a basic access control mechanism, where
2	//! there is an account (an owner) that can be granted exclusive access to
3	//! specific functions.
4	//!
5	//! The initial owner is set to the address provided by the deployer. This can
6	//! later be changed with [`Ownable::transfer_ownership`].
7	//!
8	//! This module is used through inheritance. It will make available the
9	//! [`Ownable::only_owner`] function, which can be called to restrict operations
10	//! to the owner.
11	use alloc::{vec, vec::Vec};
12	
13	use alloy_primitives::{aliases::B32, Address};
14	use openzeppelin_stylus_proc::interface_id;
15	pub use sol::*;
16	use stylus_sdk::{
17	    prelude::*, storage::StorageAddress,
18	    stylus_core::calls::errors::MethodError,
19	};
20	
21	use crate::utils::introspection::erc165::IErc165;
22	
23	#[cfg_attr(coverage_nightly, coverage(off))]
24	mod sol {
25	    use alloy_sol_macro::sol;
26	
27	    sol! {
28	        /// Emitted when ownership gets transferred between accounts.
29	        ///
30	        /// * `previous_owner` - Address of the previous owner.
31	        /// * `new_owner` - Address of the new owner.
32	        #[derive(Debug)]
33	        #[allow(missing_docs)]
34	        event OwnershipTransferred(address indexed previous_owner, address indexed new_owner);
35	    }
36	
37	    sol! {
38	        /// The caller account is not authorized to perform an operation.
39	        ///
40	        /// * `account` - Account that was found to not be authorized.
41	        #[derive(Debug)]
42	        #[allow(missing_docs)]
43	        error OwnableUnauthorizedAccount(address account);
44	        /// The owner is not a valid owner account. (eg. [`Address::ZERO`])
45	        ///
46	        /// * `owner` - Account that's not allowed to become the owner.
47	        #[derive(Debug)]
48	        #[allow(missing_docs)]
49	        error OwnableInvalidOwner(address owner);
50	    }
51	}
52	
53	/// An error that occurred in the implementation of an [`Ownable`] contract.
54	#[derive(SolidityError, Debug)]
55	pub enum Error {
56	    /// The caller account is not authorized to perform an operation.
57	    UnauthorizedAccount(OwnableUnauthorizedAccount),
58	    /// The owner is not a valid owner account. (eg. [`Address::ZERO`])
59	    InvalidOwner(OwnableInvalidOwner),
60	}
61	
62	impl MethodError for Error {
63	    fn encode(self) -> alloc::vec::Vec<u8> {
64	        self.into()
65	    }
66	}
