68	/// State of an [`Ownable`] contract.
69	#[storage]
70	pub struct Ownable {
71	    /// The current owner of this contract.
72	    pub(crate) owner: StorageAddress,
73	}
74	
75	/// Interface for an [`Ownable`] contract.
76	#[interface_id]
77	#[public]
78	// The `#[public]` macro adds an undocumented helper method to the trait.
79	#[allow(missing_docs)]
80	pub trait IOwnable {
81	    /// Returns the address of the current owner.
82	    ///
83	    /// # Arguments
84	    ///
85	    /// * `&self` - Read access to the contract's state.
86	    #[must_use]
87	    fn owner(&self) -> Address;
88	
89	    /// Transfers ownership of the contract to a new account (`new_owner`).
90	    /// Can only be called by the current owner.
91	    ///
92	    /// # Arguments
93	    ///
94	    /// * `&mut self` - Write access to the contract's state.
95	    /// * `new_owner` - The next owner of this contract.
96	    ///
97	    /// # Errors
98	    ///
99	    /// * [`OwnableInvalidOwner`] - If `new_owner` is the [`Address::ZERO`].
100	    ///
101	    /// # Events
102	    ///
103	    /// * [`OwnershipTransferred`].
104	    fn transfer_ownership(&mut self, new_owner: Address)
105	        -> Result<(), Vec<u8>>;
106	
107	    /// Leaves the contract without owner. It will not be possible to call
108	    /// functions that require `only_owner`. Can only be called by the current
109	    /// owner.
110	    ///
111	    /// NOTE: Renouncing ownership will leave the contract without an owner,
112	    /// thereby disabling any functionality that is only available to the owner.
113	    ///
114	    /// # Arguments
115	    ///
116	    /// * `&mut self` - Write access to the contract's state.
117	    ///
118	    /// # Errors
119	    ///
120	    /// * [`Error::UnauthorizedAccount`] - If not called by the owner.
121	    ///
122	    /// # Events
123	    ///
124	    /// * [`OwnershipTransferred`].
125	    fn renounce_ownership(&mut self) -> Result<(), Vec<u8>>;
126	}
127	
128	#[public]
129	#[implements(IOwnable, IErc165)]
130	impl Ownable {
131	    /// Constructor.
132	    ///
133	    /// # Arguments
134	    ///
135	    /// * `&mut self` - Write access to the contract's state.
136	    /// * `initial_owner` - The initial owner of this contract.
137	    ///
138	    /// # Errors
139	    ///
140	    /// * [`Error::InvalidOwner`] - If initial owner is [`Address::ZERO`].
141	    #[constructor]
142	    pub fn constructor(&mut self, initial_owner: Address) -> Result<(), Error> {
143	        if initial_owner.is_zero() {
144	            return Err(Error::InvalidOwner(OwnableInvalidOwner {
145	                owner: Address::ZERO,
146	            }));
147	        }
148	        self._transfer_ownership(initial_owner);
149	        Ok(())
150	    }
151	}
152	
153	#[public]
154	impl IOwnable for Ownable {
155	    fn owner(&self) -> Address {
156	        self.owner()
157	    }
158	
159	    fn transfer_ownership(
160	        &mut self,
161	        new_owner: Address,
162	    ) -> Result<(), Vec<u8>> {
163	        Ok(self.transfer_ownership(new_owner)?)
164	    }
165	
166	    fn renounce_ownership(&mut self) -> Result<(), Vec<u8>> {
167	        Ok(self.renounce_ownership()?)
168	    }
169	}
