171	impl Ownable {
172	    /// Returns the address of the current owner.
173	    ///
174	    /// # Arguments
175	    ///
176	    /// * `&self` - Read access to the contract's state.
177	    #[must_use]
178	    pub fn owner(&self) -> Address {
179	        self.owner.get()
180	    }
181	
182	    /// Transfers ownership of the contract to a new account (`new_owner`).
183	    /// Can only be called by the current owner.
184	    ///
185	    /// # Arguments
186	    ///
187	    /// * `&mut self` - Write access to the contract's state.
188	    /// * `new_owner` - The next owner of this contract.
189	    ///
190	    /// # Errors
191	    ///
192	    /// * [`Error::InvalidOwner`] - If `new_owner` is the [`Address::ZERO`].
193	    ///
194	    /// # Events
195	    ///
196	    /// * [`OwnershipTransferred`].
197	    pub fn transfer_ownership(
198	        &mut self,
199	        new_owner: Address,
200	    ) -> Result<(), Error> {
201	        self.only_owner()?;
202	
203	        if new_owner.is_zero() {
204	            return Err(Error::InvalidOwner(OwnableInvalidOwner {
205	                owner: Address::ZERO,
206	            }));
207	        }
208	
209	        self._transfer_ownership(new_owner);
210	
211	        Ok(())
212	    }
213	
214	    /// Leaves the contract without owner. It will not be possible to call
215	    /// functions that require `only_owner`. Can only be called by the current
216	    /// owner.
217	    ///
218	    /// NOTE: Renouncing ownership will leave the contract without an owner,
219	    /// thereby disabling any functionality that is only available to the owner.
220	    ///
221	    /// # Arguments
222	    ///
223	    /// * `&mut self` - Write access to the contract's state.
224	    ///
225	    /// # Errors
226	    ///
227	    /// * [`Error::UnauthorizedAccount`] - If not called by the owner.
228	    ///
229	    /// # Events
230	    ///
231	    /// * [`OwnershipTransferred`].
232	    pub fn renounce_ownership(&mut self) -> Result<(), Error> {
233	        self.only_owner()?;
234	        self._transfer_ownership(Address::ZERO);
235	        Ok(())
236	    }
237	}
238	
239	impl Ownable {
240	    /// Checks if the sender of the call (`self.vm().msg_sender()`) is set as
241	    /// the owner.
242	    ///
243	    /// # Arguments
244	    ///
245	    /// * `&self` - Read access to the contract's state.
246	    ///
247	    /// # Errors
248	    ///
249	    /// * [`Error::UnauthorizedAccount`] - If called by any account other than
250	    ///   the owner.
251	    pub fn only_owner(&self) -> Result<(), Error> {
252	        let account = self.vm().msg_sender();
253	        if self.owner() != account {
254	            return Err(Error::UnauthorizedAccount(
255	                OwnableUnauthorizedAccount { account },
256	            ));
257	        }
258	
259	        Ok(())
260	    }
261	
262	    /// Transfers ownership of the contract to a new account (`new_owner`).
263	    /// Internal function without access restriction.
264	    ///
265	    /// # Arguments
266	    ///
267	    /// * `&mut self` - Write access to the contract's state.
268	    /// * `new_owner` - Account that is going to be the next owner.
269	    ///
270	    /// # Events
271	    ///
272	    /// * [`OwnershipTransferred`].
273	    pub fn _transfer_ownership(&mut self, new_owner: Address) {
274	        let previous_owner = self.owner.get();
275	        self.owner.set(new_owner);
276	        self.vm().log(OwnershipTransferred { previous_owner, new_owner });
277	    }
278	}
279	
280	#[public]
281	impl IErc165 for Ownable {
282	    fn supports_interface(&self, interface_id: B32) -> bool {
283	        <Self as IOwnable>::interface_id() == interface_id
284	            || <Self as IErc165>::interface_id() == interface_id
285	    }
286	}
