1	//! Contract module which provides an access control mechanism, where
2	//! there is an account (an owner) that can be granted exclusive access to
3	//! specific functions.
4	//!
5	//! This extension of the `Ownable` contract includes a two-step mechanism to
6	//! transfer ownership, where the new owner must call
7	//! [`Ownable2Step::accept_ownership`] in order to replace the old one. This can
8	//! help prevent common mistakes, such as transfers of ownership to
9	//! incorrect accounts, or to contracts that are unable to interact with the
10	//! permission system.
11	//!
12	//! The initial owner is set to the address provided by the deployer. This can
13	//! later be changed with [`Ownable2Step::transfer_ownership`] and
14	//! [`Ownable2Step::accept_ownership`].
15	//!
16	//! This module uses [`Ownable`] as a member, and makes all its public functions
17	//! available.
18	
19	use alloc::{vec, vec::Vec};
20	
21	use alloy_primitives::{aliases::B32, Address};
22	use openzeppelin_stylus_proc::interface_id;
23	pub use sol::*;
24	use stylus_sdk::{prelude::*, storage::StorageAddress};
25	
26	use crate::{
27	    access::ownable::{self, Ownable},
28	    utils::introspection::erc165::IErc165,
29	};
30	
31	#[cfg_attr(coverage_nightly, coverage(off))]
32	mod sol {
33	    use alloy_sol_macro::sol;
34	
35	    sol! {
36	        /// Emitted when ownership transfer starts.
37	        ///
38	        /// * `previous_owner` - Address of the previous owner.
39	        /// * `new_owner` - Address of the new owner, to which the ownership
40	        ///   will be transferred.
41	        event OwnershipTransferStarted(
42	            address indexed previous_owner,
43	            address indexed new_owner
44	        );
45	
46	    }
47	}
48	
49	/// State of an [`Ownable2Step`] contract.
50	#[storage]
51	pub struct Ownable2Step {
52	    /// [`Ownable`] contract.
53	    // We leave the parent [`Ownable`] contract instance public, so that
54	    // inheritting contract have access to its internal functions.
55	    pub ownable: Ownable,
56	    /// Pending owner of the contract.
57	    pub(crate) pending_owner: StorageAddress,
58	}
59	
60	/// Interface for an [`Ownable2Step`] contract.
61	#[interface_id]
62	#[public]
63	// The `#[public]` macro adds an undocumented helper method to the trait.
64	#[allow(missing_docs)]
65	pub trait IOwnable2Step {
66	    /// The error type associated to the trait implementation.
67	    type Error: Into<alloc::vec::Vec<u8>>;
68	
69	    /// Returns the address of the current owner.
70	    ///
71	    /// Re-export of [`Ownable::owner`].
72	    ///
73	    /// # Arguments
74	    ///
75	    /// * `&self` - Read access to the contract's state.
76	    fn owner(&self) -> Address;
77	
78	    /// Returns the address of the pending owner.
79	    ///
80	    /// # Arguments
81	    ///
82	    /// * `&self` - Read access to the contract's state.
83	    fn pending_owner(&self) -> Address;
84	
85	    /// Starts the ownership transfer of the contract to a new account.
86	    /// Replaces the pending transfer if there is one. Can only be called by the
87	    /// current owner.
88	    ///
89	    /// Setting `new_owner` to [`Address::ZERO`] is allowed; this can be used
90	    /// to cancel an initiated ownership transfer.
91	    ///
92	    /// # Arguments
93	    ///
94	    /// * `&mut self` - Write access to the contract's state.
95	    /// * `new_owner` - The next owner of this contract.
96	    ///
97	    /// # Errors
98	    ///
99	    /// * [`ownable::Error::UnauthorizedAccount`] - If called by any account
100	    ///   other than the owner.
101	    ///
102	    /// # Events
103	    ///
104	    /// * [`OwnershipTransferStarted`].
105	    fn transfer_ownership(
106	        &mut self,
107	        new_owner: Address,
108	    ) -> Result<(), Self::Error>;
109	
110	    /// Accepts the ownership of the contract.
111	    /// Can only be called by the pending owner.
112	    ///
113	    /// # Arguments
114	    ///
115	    /// * `&mut self` - Write access to the contract's state.
116	    ///
117	    /// # Errors
118	    ///
119	    /// * [`ownable::Error::UnauthorizedAccount`] - If called by any account
120	    ///   other than the pending owner.
121	    ///
122	    /// # Events
123	    ///
124	    /// * [`crate::access::ownable::OwnershipTransferred`].
125	    fn accept_ownership(&mut self) -> Result<(), Self::Error>;
126	
127	    /// Leaves the contract without owner. It will not be possible to call
128	    /// [`Ownable::only_owner`] functions. Can only be called by the current
129	    /// owner.
130	    ///
131	    /// NOTE: Renouncing ownership will leave the contract without an owner,
132	    /// thereby disabling any functionality that is only available to the owner.
133	    ///
134	    /// # Arguments
135	    ///
136	    /// * `&mut self` - Write access to the contract's state.
137	    ///
138	    /// # Errors
139	    ///
140	    /// * [`ownable::Error::UnauthorizedAccount`] - If not called by the owner.
141	    ///
142	    /// # Events
143	    ///
144	    /// * [`crate::access::ownable::OwnershipTransferred`].
145	    fn renounce_ownership(&mut self) -> Result<(), Self::Error>;
146	}
147	
148	#[public]
149	#[implements(IOwnable2Step<Error = ownable::Error>, IErc165)]
150	impl Ownable2Step {
151	    /// See [`Ownable::constructor`].
152	    #[allow(clippy::missing_errors_doc)]
153	    #[constructor]
154	    pub fn constructor(
155	        &mut self,
156	        initial_owner: Address,
157	    ) -> Result<(), ownable::Error> {
158	        self.ownable.constructor(initial_owner)
159	    }
160	}
161	
162	#[public]
163	impl IOwnable2Step for Ownable2Step {
164	    type Error = ownable::Error;
165	
166	    fn owner(&self) -> Address {
167	        self.ownable.owner()
168	    }
169	
170	    fn pending_owner(&self) -> Address {
171	        self.pending_owner.get()
172	    }
173	
174	    fn transfer_ownership(
175	        &mut self,
176	        new_owner: Address,
177	    ) -> Result<(), ownable::Error> {
178	        self.ownable.only_owner()?;
179	        self.pending_owner.set(new_owner);
180	
181	        let current_owner = self.owner();
182	        self.vm().log(OwnershipTransferStarted {
183	            previous_owner: current_owner,
184	            new_owner,
185	        });
186	        Ok(())
187	    }
188	
189	    fn accept_ownership(&mut self) -> Result<(), ownable::Error> {
190	        let sender = self.vm().msg_sender();
191	        let pending_owner = self.pending_owner();
192	        if sender != pending_owner {
193	            return Err(ownable::Error::UnauthorizedAccount(
194	                ownable::OwnableUnauthorizedAccount { account: sender },
195	            ));
196	        }
197	        self._transfer_ownership(sender);
198	        Ok(())
199	    }
200	
201	    fn renounce_ownership(&mut self) -> Result<(), ownable::Error> {
202	        self.ownable.only_owner()?;
203	        self._transfer_ownership(Address::ZERO);
204	        Ok(())
205	    }
206	}
207	
208	impl Ownable2Step {
209	    /// Transfers ownership of the contract to a new account (`new_owner`) and
210	    /// sets [`Self::pending_owner`] to [`Address::ZERO`] to avoid situations
211	    /// where the transfer has been completed or the current owner renounces,
212	    /// but [`Self::pending_owner`] can still accept ownership.
213	    ///
214	    /// Internal function without access restriction.
215	    ///
216	    /// # Arguments
217	    ///
218	    /// * `&mut self` - Write access to the contract's state.
219	    /// * `new_owner` - Account that's gonna be the next owner.
220	    ///
221	    /// # Events
222	    ///
223	    /// * [`crate::access::ownable::OwnershipTransferred`].
224	    fn _transfer_ownership(&mut self, new_owner: Address) {
225	        self.pending_owner.set(Address::ZERO);
226	        self.ownable._transfer_ownership(new_owner);
227	    }
228	}
229	
230	#[public]
231	impl IErc165 for Ownable2Step {
232	    fn supports_interface(&self, interface_id: B32) -> bool {
233	        <Self as IOwnable2Step>::interface_id() == interface_id
234	            || self.ownable.supports_interface(interface_id)
235	            || <Self as IErc165>::interface_id() == interface_id
236	    }
237	}
