27	    sol! {
28	        /// Emitted when ownership gets transferred between accounts.
29	        ///
30	        /// * `previous_owner` - Address of the previous owner.
31	        /// * `new_owner` - Address of the new owner.
32	        #[derive(Debug)]
33	        #[allow(missing_docs)]
34	        event OwnershipTransferred(address indexed previous_owner, address indexed new_owner);
35	    }
36	
37	    sol! {
38	        /// The caller account is not authorized to perform an operation.
39	        ///
40	        /// * `account` - Account that was found to not be authorized.
41	        #[derive(Debug)]
42	        #[allow(missing_docs)]
43	        error OwnableUnauthorizedAccount(address account);
44	        /// The owner is not a valid owner account. (eg. [`Address::ZERO`])
45	        ///
46	        /// * `owner` - Account that's not allowed to become the owner.
47	        #[derive(Debug)]
48	        #[allow(missing_docs)]
49	        error OwnableInvalidOwner(address owner);
50	    }
51	}
