77	#[public]
78	// The `#[public]` macro adds an undocumented helper method to the trait.
79	#[allow(missing_docs)]
80	pub trait IOwnable {
81	    /// Returns the address of the current owner.
82	    ///
83	    /// # Arguments
84	    ///
85	    /// * `&self` - Read access to the contract's state.
86	    #[must_use]
87	    fn owner(&self) -> Address;
88	
89	    /// Transfers ownership of the contract to a new account (`new_owner`).
90	    /// Can only be called by the current owner.
91	    ///
92	    /// # Arguments
93	    ///
94	    /// * `&mut self` - Write access to the contract's state.
95	    /// * `new_owner` - The next owner of this contract.
96	    ///
97	    /// # Errors
98	    ///
99	    /// * [`OwnableInvalidOwner`] - If `new_owner` is the [`Address::ZERO`].
100	    ///
101	    /// # Events
102	    ///
103	    /// * [`OwnershipTransferred`].
104	    fn transfer_ownership(&mut self, new_owner: Address)
105	        -> Result<(), Vec<u8>>;
106	
107	    /// Leaves the contract without owner. It will not be possible to call
108	    /// functions that require `only_owner`. Can only be called by the current
109	    /// owner.
110	    ///
111	    /// NOTE: Renouncing ownership will leave the contract without an owner,
112	    /// thereby disabling any functionality that is only available to the owner.
113	    ///
114	    /// # Arguments
115	    ///
116	    /// * `&mut self` - Write access to the contract's state.
117	    ///
118	    /// # Errors
119	    ///
120	    /// * [`Error::UnauthorizedAccount`] - If not called by the owner.
121	    ///
122	    /// # Events
123	    ///
124	    /// * [`OwnershipTransferred`].
125	    fn renounce_ownership(&mut self) -> Result<(), Vec<u8>>;
126	}
