128	#[public]
129	#[implements(IOwnable, IErc165)]
130	impl Ownable {
131	    /// Constructor.
132	    ///
133	    /// # Arguments
134	    ///
135	    /// * `&mut self` - Write access to the contract's state.
136	    /// * `initial_owner` - The initial owner of this contract.
137	    ///
138	    /// # Errors
139	    ///
140	    /// * [`Error::InvalidOwner`] - If initial owner is [`Address::ZERO`].
141	    #[constructor]
142	    pub fn constructor(&mut self, initial_owner: Address) -> Result<(), Error> {
143	        if initial_owner.is_zero() {
144	            return Err(Error::InvalidOwner(OwnableInvalidOwner {
145	                owner: Address::ZERO,
146	            }));
147	        }
148	        self._transfer_ownership(initial_owner);
149	        Ok(())
150	    }
151	}
