153	#[public]
154	impl IOwnable for Ownable {
155	    fn owner(&self) -> Address {
156	        self.owner()
157	    }
158	
159	    fn transfer_ownership(
160	        &mut self,
161	        new_owner: Address,
162	    ) -> Result<(), Vec<u8>> {
163	        Ok(self.transfer_ownership(new_owner)?)
164	    }
165	
166	    fn renounce_ownership(&mut self) -> Result<(), Vec<u8>> {
167	        Ok(self.renounce_ownership()?)
168	    }
169	}
