162	#[public]
163	impl IOwnable2Step for Ownable2Step {
164	    type Error = ownable::Error;
165	
166	    fn owner(&self) -> Address {
167	        self.ownable.owner()
168	    }
169	
170	    fn pending_owner(&self) -> Address {
171	        self.pending_owner.get()
172	    }
173	
174	    fn transfer_ownership(
175	        &mut self,
176	        new_owner: Address,
177	    ) -> Result<(), ownable::Error> {
178	        self.ownable.only_owner()?;
179	        self.pending_owner.set(new_owner);
180	
181	        let current_owner = self.owner();
182	        self.vm().log(OwnershipTransferStarted {
183	            previous_owner: current_owner,
184	            new_owner,
185	        });
186	        Ok(())
187	    }
188	
189	    fn accept_ownership(&mut self) -> Result<(), ownable::Error> {
190	        let sender = self.vm().msg_sender();
191	        let pending_owner = self.pending_owner();
192	        if sender != pending_owner {
193	            return Err(ownable::Error::UnauthorizedAccount(
194	                ownable::OwnableUnauthorizedAccount { account: sender },
195	            ));
196	        }
197	        self._transfer_ownership(sender);
198	        Ok(())
199	    }
200	
201	    fn renounce_ownership(&mut self) -> Result<(), ownable::Error> {
202	        self.ownable.only_owner()?;
203	        self._transfer_ownership(Address::ZERO);
204	        Ok(())
205	    }
206	}
