1	//! Contract module that allows children to implement role-based access control
2	//! mechanisms.
3	//!
4	//! This is a lightweight version that doesn't allow enumerating role members
5	//! except through off-chain means by accessing the contract event logs.
6	//!
7	//! Roles are referred to by their `bytes32` identifier. These should be exposed
8	//! in the external API and be unique. The best way to achieve this is by using
9	//! `pub const` hash digests:
10	//!
11	//! ```no_run
12	//! pub const MY_ROLE: [u8; 32] =
13	//!     keccak_const::Keccak256::new().update(b"MY_ROLE").finalize();
14	//! ```
15	//!
16	//! Roles can be used to represent a set of permissions. To restrict access to a
17	//! function call, use [`IAccessControl::has_role`]:
18	//!
19	//! ```rust,ignore
20	//! pub fn foo() {
21	//!   assert!(self.has_role(MY_ROLE.into(), self.vm().msg_sender()));
22	//!   // ...
23	//! }
24	//! ```
25	//!
26	//! Roles can be granted and revoked dynamically via the
27	//! [`IAccessControl::grant_role`] and [`IAccessControl::revoke_role`]
28	//! functions. Each role has an associated admin role, and only accounts that
29	//! have a `role`'s `admin_role` can call [`IAccessControl::grant_role`] and
30	//! [`IAccessControl::revoke_role`].
31	//!
32	//! By default, the admin role for all roles is
33	//! [`AccessControl::DEFAULT_ADMIN_ROLE`], which means that only accounts with
34	//! this role will be able to grant or revoke other roles. More complex role
35	//! relationships can be created by using [`AccessControl::_set_role_admin`].
36	//!
37	//! WARNING: The [`AccessControl::DEFAULT_ADMIN_ROLE`] is also its own admin: it
38	//! has permission to grant and revoke this role. Extra precautions should be
39	//! taken to secure accounts that have been granted it. We recommend using
40	//! `AccessControlDefaultAdminRules` to enforce additional security measures for
41	//! this role.
42	use alloc::{vec, vec::Vec};
43	
44	use alloy_primitives::{aliases::B32, Address, B256};
45	use openzeppelin_stylus_proc::interface_id;
46	pub use sol::*;
47	use stylus_sdk::{
48	    prelude::*,
49	    storage::{StorageB256, StorageBool, StorageMap},
50	    stylus_core::calls::errors::MethodError,
51	};
