92	        /// * `account` - Account that was found to not be authorized.
93	        /// * `needed_role` - The missing role.
94	        #[derive(Debug)]
95	        #[allow(missing_docs)]
96	        error AccessControlUnauthorizedAccount(address account, bytes32 needed_role);
97	        /// The caller of a function is not the expected one.
98	        ///
99	        /// NOTE: Don't confuse with [`AccessControlUnauthorizedAccount`].
100	        #[derive(Debug)]
101	        #[allow(missing_docs)]
102	        error AccessControlBadConfirmation();
103	    }
104	}
