144	#[allow(missing_docs)]
145	pub trait IAccessControl {
146	    /// The error type associated with this interface implementation.
147	    type Error: Into<alloc::vec::Vec<u8>>;
148	
149	    /// Returns `true` if `account` has been granted `role`.
150	    ///
151	    /// # Arguments
152	    ///
153	    /// * `&self` - Read access to the contract's state.
154	    /// * `role` - The role identifier.
155	    /// * `account` - The account to check for membership.
156	    fn has_role(&self, role: B256, account: Address) -> bool;
157	
158	    /// Checks if the sender of the call (`self.vm().msg_sender()`) has been
159	    /// granted `role`.
160	    ///
161	    /// # Arguments
162	    ///
163	    /// * `&self` - Read access to the contract's state.
164	    /// * `role` - The role identifier.
165	    ///
166	    /// # Errors
167	    ///
168	    /// * [`Error::UnauthorizedAccount`] - If the sender of the call has not
169	    ///   been granted `role`.
170	    fn only_role(&self, role: B256) -> Result<(), Self::Error>;
171	
172	    /// Returns the admin role that controls `role`. See
173	    /// [`IAccessControl::grant_role`] and [`IAccessControl::revoke_role`].
174	    ///
175	    /// To change a role's admin, use [`AccessControl::_set_role_admin`].
176	    ///
177	    /// # Arguments
178	    ///
179	    /// * `&self` - Read access to the contract's state.
180	    /// * `role` - The role identifier.
181	    fn get_role_admin(&self, role: B256) -> B256;
182	
183	    /// Grants `role` to `account`.
184	    ///
185	    /// If `account` had not been already granted `role`, emits a
186	    /// [`RoleGranted`] event.
187	    ///
188	    /// # Arguments
189	    ///
190	    /// * `&mut self` - Write access to the contract's state.
191	    /// * `role` - The role identifier.
192	    /// * `account` - The account which will be granted the role.
193	    ///
194	    /// # Errors
195	    ///
196	    /// * [`Error::UnauthorizedAccount`] - If the sender of the call has not
197	    ///   been granted `role`.
198	    ///
199	    /// # Events
200	    ///
201	    /// * [`RoleGranted`]
202	    fn grant_role(
203	        &mut self,
204	        role: B256,
205	        account: Address,
206	    ) -> Result<(), Self::Error>;
207	
208	    /// Revokes `role` from `account`.
209	    ///
210	    /// If `account` had been granted `role`, emits a [`RoleRevoked`] event.
211	    ///
212	    /// # Arguments
213	    ///
214	    /// * `&mut self` - Write access to the contract's state.
215	    /// * `role` - The role identifier.
216	    /// * `account` - The account which will be revoked the role.
217	    ///
218	    /// # Errors
219	    ///
220	    /// * [`Error::UnauthorizedAccount`] - If the sender of the call has not
221	    ///   been granted `role`.
222	    ///
223	    /// # Events
224	    ///
225	    /// * [`RoleRevoked`].
226	    fn revoke_role(
227	        &mut self,
228	        role: B256,
229	        account: Address,
230	    ) -> Result<(), Self::Error>;
231	
232	    /// Revokes `role` from the calling account.
233	    ///
234	    /// Roles are often managed via [`Self::grant_role`] and
235	    /// [`Self::revoke_role`]: this function's purpose is to provide a mechanism
236	    /// for accounts to lose their privileges if they are compromised (such as
237	    /// when a trusted device is misplaced).
238	    ///
239	    /// # Arguments
240	    ///
241	    /// * `&mut self` - Write access to the contract's state.
242	    /// * `role` - The role identifier.
243	    /// * `confirmation` - The account which will be revoked the role.
244	    ///
245	    /// # Errors
246	    ///
247	    /// * [`Error::BadConfirmation`]  - If the sender of the call is not the
248	    ///   `confirmation` address.
249	    ///
250	    /// # Events
251	    ///
252	    /// * [`RoleRevoked`] - If the calling account has its `role` revoked.
253	    fn renounce_role(
254	        &mut self,
255	        role: B256,
256	        confirmation: Address,
257	    ) -> Result<(), Self::Error>;
258	}
