318	impl AccessControl {
319	    /// The default admin role. `[0; 32]` by default.
320	    pub const DEFAULT_ADMIN_ROLE: [u8; 32] = [0; 32];
321	
322	    /// Sets `admin_role` as `role`'s admin role.
323	    ///
324	    /// # Arguments
325	    ///
326	    /// * `&mut self` - Write access to the contract's state.
327	    /// * `role` - The identifier of the role we are changing the admin to.
328	    /// * `new_admin_role` - The new admin role.
329	    ///
330	    /// # Events
331	    ///
332	    /// * [`RoleAdminChanged`].
333	    pub fn _set_role_admin(&mut self, role: B256, new_admin_role: B256) {
334	        let previous_admin_role = self.get_role_admin(role);
335	        self.roles.setter(role).admin_role.set(new_admin_role);
336	        self.vm().log(RoleAdminChanged {
337	            role,
338	            previous_admin_role,
339	            new_admin_role,
340	        });
341	    }
342	
343	    /// Checks if `account` has been granted `role`.
344	    ///
345	    /// # Arguments
346	    ///
347	    /// * `&self` - Read access to the contract's state.
348	    /// * `role` - The role identifier.
349	    /// * `account` - The account to check for membership.
350	    ///
351	    /// # Errors
352	    ///
353	    /// * [`Error::UnauthorizedAccount`] - If `account` has not been granted
354	    ///   `role`.
355	    pub fn _check_role(
356	        &self,
357	        role: B256,
358	        account: Address,
359	    ) -> Result<(), Error> {
360	        if !self.has_role(role, account) {
361	            return Err(Error::UnauthorizedAccount(
362	                AccessControlUnauthorizedAccount { account, needed_role: role },
363	            ));
364	        }
365	
366	        Ok(())
367	    }
368	
369	    /// Attempts to grant `role` to `account` and returns a boolean indicating
370	    /// if `role` was granted.
371	    ///
372	    /// Internal function without access restriction.
373	    ///
374	    /// # Arguments
375	    ///
376	    /// * `&mut self` - Write access to the contract's state.
377	    /// * `role` - The role identifier.
378	    /// * `account` - The account which will be granted the role.
379	    ///
380	    /// # Events
381	    ///
382	    /// * [`RoleGranted`].
383	    pub fn _grant_role(&mut self, role: B256, account: Address) -> bool {
384	        if self.has_role(role, account) {
385	            false
386	        } else {
387	            self.roles.setter(role).has_role.insert(account, true);
388	            self.vm().log(RoleGranted {
389	                role,
390	                account,
391	                sender: self.vm().msg_sender(),
392	            });
393	            true
394	        }
395	    }
396	
397	    /// Attempts to revoke `role` from `account` and returns a boolean
398	    /// indicating if `role` was revoked.
399	    ///
400	    /// Internal function without access restriction.
401	    ///
402	    /// # Arguments
403	    ///
404	    /// * `&mut self` - Write access to the contract's state.
405	    /// * `role` - The role identifier.
406	    /// * `account` - The account which will be granted the role.
407	    ///
408	    /// # Events
409	    ///
410	    /// * [`RoleRevoked`].
411	    pub fn _revoke_role(&mut self, role: B256, account: Address) -> bool {
412	        if self.has_role(role, account) {
413	            self.roles.setter(role).has_role.insert(account, false);
414	            self.vm().log(RoleRevoked {
415	                role,
416	                account,
417	                sender: self.vm().msg_sender(),
418	            });
419	            true
420	        } else {
421	            false
422	        }
423	    }
424	}
