134	    #[allow(clippy::missing_errors_doc)]
135	    pub fn _grant_role(
136	        &mut self,
137	        role: B256,
138	        account: Address,
139	        access_control: &mut AccessControl,
140	    ) -> bool {
141	        let granted = access_control._grant_role(role, account);
142	
143	        if granted {
144	            self.role_members.setter(role).add(account);
145	        }
146	
147	        granted
148	    }
149	
150	    /// Extension of [`AccessControl::_revoke_role`] that removes the `account`
151	    /// from `role`'s members list.
152	    #[allow(clippy::missing_errors_doc)]
153	    pub fn _revoke_role(
154	        &mut self,
155	        role: B256,
156	        account: Address,
157	        access_control: &mut AccessControl,
158	    ) -> bool {
159	        let revoked = access_control._revoke_role(role, account);
160	
161	        if revoked {
162	            self.role_members.setter(role).remove(account);
163	        }
164	
165	        revoked
166	    }
167	}
