60	
61	    sol! {
62	        /// Emitted when `new_admin_role` is set as `role`'s admin role, replacing
63	        /// `previous_admin_role`.
64	        ///
65	        /// `DEFAULT_ADMIN_ROLE` is the starting admin for all roles, despite
66	        /// `RoleAdminChanged` not being emitted signaling this.
67	        #[derive(Debug)]
68	        #[allow(missing_docs)]
69	        event RoleAdminChanged(bytes32 indexed role, bytes32 indexed previous_admin_role, bytes32 indexed new_admin_role);
70	        /// Emitted when `account` is granted `role`.
71	        ///
72	        /// `sender` is the account that originated the contract call. This account
73	        /// bears the admin role (for the granted role).
74	        /// Expected in cases where the role was granted using the internal
75	        /// [`AccessControl::grant_role`].
76	        #[derive(Debug)]
77	        #[allow(missing_docs)]
78	        event RoleGranted(bytes32 indexed role, address indexed account, address indexed sender);
79	        /// Emitted when `account` is revoked `role`.
80	        ///
81	        /// `sender` is the account that originated the contract call:
82	        ///   - if using `revoke_role`, it is the admin role bearer.
83	        ///   - if using `renounce_role`, it is the role bearer (i.e. `account`).
84	        #[derive(Debug)]
85	        #[allow(missing_docs)]
86	        event RoleRevoked(bytes32 indexed role, address indexed account, address indexed sender);
87	    }
