268	    fn has_role(&self, role: B256, account: Address) -> bool {
269	        self.roles.getter(role).has_role.get(account)
270	    }
271	
272	    fn only_role(&self, role: B256) -> Result<(), Error> {
273	        self._check_role(role, self.vm().msg_sender())
274	    }
275	
276	    fn get_role_admin(&self, role: B256) -> B256 {
277	        self.roles.getter(role).admin_role.get()
278	    }
279	
280	    fn grant_role(
281	        &mut self,
282	        role: B256,
283	        account: Address,
284	    ) -> Result<(), Error> {
285	        let admin_role = self.get_role_admin(role);
286	        self.only_role(admin_role)?;
287	        self._grant_role(role, account);
288	        Ok(())
289	    }
290	
291	    fn revoke_role(
292	        &mut self,
293	        role: B256,
294	        account: Address,
295	    ) -> Result<(), Error> {
296	        let admin_role = self.get_role_admin(role);
297	        self.only_role(admin_role)?;
298	        self._revoke_role(role, account);
299	        Ok(())
300	    }
