302	    fn renounce_role(
303	        &mut self,
304	        role: B256,
305	        confirmation: Address,
306	    ) -> Result<(), Error> {
307	        if self.vm().msg_sender() != confirmation {
308	            return Err(Error::BadConfirmation(
309	                AccessControlBadConfirmation {},
310	            ));
311	        }
312	
313	        self._revoke_role(role, confirmation);
314	        Ok(())
