45	/// Interface for the [`AccessControlEnumerable`] extension.
46	#[interface_id]
47	#[public]
48	// The `#[public]` macro adds an undocumented helper method to the trait.
49	#[allow(missing_docs)]
50	pub trait IAccessControlEnumerable {
51	    /// The error type associated to the trait implementation.
52	    type Error: Into<alloc::vec::Vec<u8>>;
53	
54	    /// Returns one of the accounts that have `role`.
55	    ///
56	    /// # Arguments
57	    ///
58	    /// * `&self` - Read access to the contract's state.
59	    /// * `role` - The role identifier.
60	    /// * `index` - The index of the account at `role`'s members list.
61	    ///
62	    /// # Errors
63	    ///
64	    /// * [`Error::OutOfBounds`] - If `index` is out of bounds.
65	    fn get_role_member(
66	        &self,
67	        role: B256,
68	        index: U256,
69	    ) -> Result<Address, Error>;
70	
71	    /// Returns the number of accounts that have role.
72	    ///
73	    /// # Arguments
74	    ///
75	    /// * `&self` - Read access to the contract's state.
76	    /// * `role` - The role identifier.
77	    fn get_role_member_count(&self, role: B256) -> U256;
78	}
