80	#[public]
81	#[implements(IAccessControlEnumerable<Error = Error>, IErc165)]
82	impl AccessControlEnumerable {
83	    /// Returns the members of `role`.
84	    ///
85	    /// # WARNING
86	    ///
87	    /// This operation will copy the entire storage to memory, which can be
88	    /// quite expensive. This is designed to mostly be used by view
89	    /// accessors that are queried without any gas fees. Developers should keep
90	    /// in mind that this function has an unbounded cost, and using it as
91	    /// part of a state-changing function may render the function uncallable
92	    /// if the set grows to a point where copying to memory consumes too much
93	    /// gas to fit in a block.
94	    ///
95	    /// # Arguments
96	    ///
97	    /// * `&self` - Read access to the contract's state.
98	    /// * `role` - The role identifier.
99	    #[must_use]
100	    pub fn get_role_members(&self, role: B256) -> Vec<Address> {
101	        self.role_members.get(role).values()
102	    }
103	}
104	
105	#[public]
106	impl IAccessControlEnumerable for AccessControlEnumerable {
107	    type Error = Error;
108	
109	    fn get_role_member(
110	        &self,
111	        role: B256,
112	        index: U256,
113	    ) -> Result<Address, Error> {
114	        let members = self.role_members.get(role);
115	        match members.at(index) {
116	            Some(member) => Ok(member),
117	            None => {
118	                Err(Error::OutOfBounds(AccessControlEnumerableOutOfBounds {
119	                    role,
120	                    index,
121	                }))
122	            }
123	        }
124	    }
125	
126	    fn get_role_member_count(&self, role: B256) -> U256 {
127	        self.role_members.get(role).length()
128	    }
129	}
