221	        fn get_role_admin(&self, role: B256) -> B256 {
222	            self.access_control.get_role_admin(role)
223	        }
224	
225	        fn grant_role(
226	            &mut self,
227	            role: B256,
228	            account: Address,
229	        ) -> Result<(), Self::Error> {
230	            let admin_role = self.get_role_admin(role);
231	            self.only_role(admin_role)?;
232	            self.enumerable._grant_role(
233	                role,
234	                account,
235	                &mut self.access_control,
236	            );
237	            Ok(())
238	        }
239	
240	        fn revoke_role(
241	            &mut self,
242	            role: B256,
243	            account: Address,
244	        ) -> Result<(), Self::Error> {
245	            let admin_role = self.get_role_admin(role);
246	            self.only_role(admin_role)?;
247	            self.enumerable._revoke_role(
248	                role,
249	                account,
250	                &mut self.access_control,
251	            );
252	            Ok(())
253	        }
254	
255	        fn renounce_role(
256	            &mut self,
257	            role: B256,
258	            confirmation: Address,
259	        ) -> Result<(), Self::Error> {
260	            if self.vm().msg_sender() != confirmation {
261	                return Err(control::Error::BadConfirmation(
262	                    control::AccessControlBadConfirmation {},
263	                ));
264	            }
265	
266	            self.enumerable._revoke_role(
267	                role,
268	                confirmation,
269	                &mut self.access_control,
270	            );
271	            Ok(())
272	        }
273	    }
